validator:
function validate(input) {
  const [{ Problems = [] }] = input;
  const ids = new Set();
  for (const [id, likes, dislikes] of Problems) {
    if (id === null || likes === null || dislikes === null) return 'Every column is required.';
    if (ids.has(id)) return `problem_id ${id} appears twice.`;
    ids.add(id);
    if (likes < 0 || dislikes < 0) return 'Vote counts cannot be negative.';
    if (likes + dislikes === 0) return `Problem ${id} has no votes.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const rows = small ? Math.floor(rand() * 9) : 2000;
  const ids = Array.from({ length: small ? 20 : 5000 }, (_, i) => i + 1);
  for (let i = ids.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [ids[i], ids[j]] = [ids[j], ids[i]]; }
  // Vote totals stay below 2000 so no ratio sits within 0.0001 of 0.6 unless it is exactly 0.6.
  const Problems = [];
  for (let i = 0; i < rows; i++) {
    let likes, dislikes;
    if (rand() < 0.4) {
      // Near the boundary: exactly 60%, or one vote either side of it.
      const k = 1 + Math.floor(rand() * (small ? 20 : 399)), shift = [-1, 0, 0, 1][Math.floor(rand() * 4)];
      likes = 3 * k + shift;
      dislikes = 2 * k - shift;
    } else {
      likes = Math.floor(rand() * (small ? 30 : 1000));
      dislikes = Math.floor(rand() * (small ? 30 : 1000));
      if (likes + dislikes === 0) dislikes = 1;
    }
    Problems.push([ids[i], likes, dislikes]);
  }
  return [{ Problems }];
}
